import assert from "node:assert/strict";
import { ProfileCache } from "./profileCache.ts";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
let calls = 0;
const load = async (id: string) => { calls++; await sleep(10); return { id, n: calls }; };

const c = new ProfileCache<{ id: string; n: number }>({ ttlMs: 50, maxEntries: 2 });
