await c.get("2", load); assert.equal(calls, before + 1);
// errors not cached
let fails = 0;
const bad = async () => { fails++; throw new Error("x"); };
await assert.rejects(c.get("9", bad)); await assert.rejects(c.get("9", bad)); assert.equal(fails, 2);
console.log("ok");
